-- ============================================================
-- Migration: ALE-LAWS Taxonomy Expansion (Option A)
-- 
-- WHAT THIS DOES:
--   1. Updates 8 topic node names (clarified titles)
--   2. Deprecates all 48 old ALE-LAWS-NNN-NN subtopics
--      (sets deprecated_at = now(), does NOT delete)
--   3. Inserts 55 new ALE-LAWS-NNN-NNN subtopics
--
-- WHY OPTION A (not edit-in-place):
--   Old format: ALE-LAWS-001-01 (law-as-whole, e.g. "RA 9266")
--   New format: ALE-LAWS-001-001 (provision-level, e.g. "Board Composition")
--   These are different granularity nodes, not renames.
--   All ALE-LAWS nodes are is_cross_ref_only=true — zero questions,
--   zero user mastery, zero user interactions reference them.
--   Safe to deprecate.
--
-- IDEMPOTENT: ON CONFLICT DO UPDATE throughout
-- ============================================================

-- Preflight: confirm no questions reference ALE-LAWS nodes
DO $$
DECLARE
  v_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM public.questions q
  JOIN public.taxonomy_tree tt ON tt.node_id = q.topic_id
  WHERE tt.ale_id LIKE 'ALE-LAWS-%';
  
  IF v_count > 0 THEN
    RAISE EXCEPTION 'ABORT: % question(s) still reference ALE-LAWS nodes. The trg_check_question_topic trigger should have prevented this. Investigate before proceeding.', v_count;
  END IF;
  
  RAISE NOTICE 'Preflight passed: 0 questions reference ALE-LAWS nodes.';
END $$;

-- ── Step 1: Update ALE-LAWS topic names (8 topics) ─────────────────
UPDATE public.taxonomy_tree SET name = 'Professional Regulation Laws (RA 9266 & Related)', updated_at = now() WHERE ale_id = 'ALE-LAWS-001';
UPDATE public.taxonomy_tree SET name = 'Building Standards & Development Controls (PD 1096 NBCP)', updated_at = now() WHERE ale_id = 'ALE-LAWS-002';
UPDATE public.taxonomy_tree SET name = 'Housing & Land Development Laws (BP 220, PD 957)', updated_at = now() WHERE ale_id = 'ALE-LAWS-003';
UPDATE public.taxonomy_tree SET name = 'Safety, Fire, Environmental & Disaster Laws (RA 9514, BP 344, Environmental Laws)', updated_at = now() WHERE ale_id = 'ALE-LAWS-004';
UPDATE public.taxonomy_tree SET name = 'Heritage, Utilities & Cross-Border Professional Practice', updated_at = now() WHERE ale_id = 'ALE-LAWS-005';
UPDATE public.taxonomy_tree SET name = 'Allied Professions & Regulatory Framework', updated_at = now() WHERE ale_id = 'ALE-LAWS-006';
UPDATE public.taxonomy_tree SET name = 'Civil/Labor/Administrative Laws & Contracts', updated_at = now() WHERE ale_id = 'ALE-LAWS-008';

