-- ── Step 4: Ensure all ALE-LAWS nodes remain is_cross_ref_only = true ────
WITH RECURSIVE laws_tree AS (
  SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-LAWS'
  UNION ALL
  SELECT t.node_id FROM public.taxonomy_tree t
  JOIN laws_tree lt ON t.parent_id = lt.node_id
)
UPDATE public.taxonomy_tree SET is_cross_ref_only = true
WHERE node_id IN (SELECT node_id FROM laws_tree) AND is_cross_ref_only = false;

-- ── Step 5: Verify ────────────────────────────────────────────────────────
DO $$
DECLARE
  v_deprecated INTEGER;
  v_new        INTEGER;
  v_non_xref   INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_deprecated FROM public.taxonomy_tree
  WHERE ale_id LIKE 'ALE-LAWS-___-__' AND deprecated_at IS NOT NULL;
  
  SELECT COUNT(*) INTO v_new FROM public.taxonomy_tree
  WHERE ale_id LIKE 'ALE-LAWS-___-___' AND deprecated_at IS NULL;
  
  SELECT COUNT(*) INTO v_non_xref FROM public.taxonomy_tree
  WHERE ale_id LIKE 'ALE-LAWS%' AND is_cross_ref_only = false;
  
  RAISE NOTICE '=== ALE-LAWS Expansion (Option A) Complete ===';
  RAISE NOTICE 'Old subtopics deprecated:   % (expected 48)', v_deprecated;
  RAISE NOTICE 'New subtopics active:        % (expected 55)', v_new;
  RAISE NOTICE 'Non-crossref ALE-LAWS nodes: % (MUST be 0)', v_non_xref;
  
  IF v_non_xref > 0 THEN
    RAISE EXCEPTION 'CRITICAL: % ALE-LAWS nodes not marked is_cross_ref_only. Fix immediately.', v_non_xref;
  END IF;
END $$;